import { useCallback, useEffect, useRef, useState } from 'react';
import { ArrowRight } from 'lucide-react';
import type { ChangeoverResponse } from '../types';
import SourceNote from './SourceNote';
import { PanelSkeleton } from './PanelStates';

/** One pre→post metric tile; null renders the explicit-unavailable state. */
function Tile({
  label,
  pre,
  post,
  fmt,
}: {
  label: string;
  pre: number | null;
  post: number | null;
  fmt: (v: number) => string;
}) {
  return (
    <div className="rounded-xl border border-border bg-card p-4">
      <div className="text-[10px] font-bold uppercase tracking-wider text-text-muted">{label}</div>
      {pre === null ? (
        <div className="mt-1 text-sm text-text-muted">— (no pre-block baseline yet)</div>
      ) : post === null ? (
        <div className="mt-1">
          <div className="text-lg font-semibold text-text-primary">{fmt(pre)}</div>
          <div className="text-xs text-text-muted">pre-block baseline · awaiting post</div>
        </div>
      ) : (
        <div className="mt-1 flex items-baseline gap-2">
          <span className="text-lg font-semibold text-text-primary">{fmt(pre)}</span>
          <ArrowRight className="h-3.5 w-3.5 self-center text-text-muted" />
          <span className="text-lg font-semibold text-text-primary">{fmt(post)}</span>
        </div>
      )}
    </div>
  );
}

/** Changeover Impact — the measured before/after of the Sept 8 schedule change.
 * Every number is a collector measurement; see docs/CHANGEOVER-IMPACT-DESIGN.md. */
export default function ChangeoverPanel() {
  const [data, setData] = useState<ChangeoverResponse | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  // P0.8: one AbortController per in-flight load — aborted by the next tick
  // or unmount (the collector appends continuously; a stale response is
  // worse than an aborted request). Same doctrine as CoveragePanel.
  const abortRef = useRef<AbortController | null>(null);

  const load = useCallback(async () => {
    abortRef.current?.abort();
    const controller = new AbortController();
    abortRef.current = controller;
    try {
      const r = await fetch('/api/changeover', { signal: controller.signal });
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      const json = (await r.json()) as ChangeoverResponse;
      if (controller.signal.aborted) return; // stale poll: don't touch state
      setData(json);
      setError(null);
    } catch (e) {
      if (controller.signal.aborted) return; // aborted: not an error
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      if (!controller.signal.aborted) setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
    // The collector appends continuously; refresh while on screen.
    timerRef.current = setInterval(() => void load(), 120_000);
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
      abortRef.current?.abort(); // unmount: in-flight poll is stale by definition
    };
  }, [load]);

  if (loading && !data) return <PanelSkeleton label="Loading changeover comparison…" />;
  if (error && !data) {
    return (
      <div role="alert" className="rounded-xl border border-danger/40 bg-danger/10 p-6 text-sm text-danger">
        Could not load changeover comparison: {error}
      </div>
    );
  }
  if (!data) return null;

  if (!data.available) {
    return (
      <div className="mx-auto max-w-3xl space-y-4 p-2">
        <h1 className="text-xl font-bold text-text-primary">Changeover Impact</h1>
        <div className="rounded-xl border border-border bg-card p-6 text-sm text-text-secondary">
          {data.reason ?? 'Not available.'}
        </div>
      </div>
    );
  }

  const { pre, post } = data;
  const delta = pre.pct_on_time !== null && post.pct_on_time !== null
    ? Math.round((post.pct_on_time - pre.pct_on_time) * 10) / 10
    : null;
  const cutoffPretty = data.cutoff
    ? `${data.cutoff.slice(0, 4)}-${data.cutoff.slice(4, 6)}-${data.cutoff.slice(6)}`
    : '?';

  return (
    <div className="mx-auto max-w-3xl space-y-4 p-2">
      <div>
        <h1 className="text-xl font-bold text-text-primary">Changeover Impact</h1>
        <p className="text-xs text-text-muted">
          Measured before/after of the timetable that started {cutoffPretty}. Weekdays only,
          holidays excluded, same collection streams on both sides.
        </p>
      </div>

      {/* Verdict card */}
      <div className="rounded-xl border border-border bg-card p-5">
        {post.days === 0 ? (
          <p className="text-sm text-text-secondary">{data.reason}</p>
        ) : !data.verdict_ready ? (
          <div>
            <p className="text-sm text-text-secondary">
              On the new timetable so far: <span className="font-semibold text-text-primary">{post.pct_on_time}%</span>{' '}
              on-time across {post.n_departures.toLocaleString()} recorded departures ({post.days}{' '}
              day{post.days === 1 ? '' : 's'}).
            </p>
            <p className="mt-2 text-xs text-text-muted">{data.reason}</p>
          </div>
        ) : (
          <p className="text-sm text-text-secondary">
            On the new timetable, transfer on-time is{' '}
            <span className="font-semibold text-optimized">{post.pct_on_time}%</span> of{' '}
            {post.n_departures.toLocaleString()} recorded departures across {post.days} days — was{' '}
            <span className="font-semibold text-text-primary">{pre.pct_on_time}%</span> on the old one (
            <span className={delta !== null && delta < 0 ? 'font-semibold text-bottleneck' : 'font-semibold text-optimized'}>
              {delta !== null && delta > 0 ? '+' : ''}
              {delta} pp
            </span>
            , measured).
          </p>
        )}
      </div>

      {/* System tiles */}
      <div className="grid grid-cols-1 gap-3 sm:grid-cols-3">
        <Tile label="Mean lateness (min)" pre={pre.mean_lateness_min} post={post.mean_lateness_min} fmt={(v) => `${v > 0 ? '+' : ''}${v}`} />
        <Tile label="Ghost rate (%)" pre={data.ghost_rate.pre} post={data.ghost_rate.post} fmt={(v) => `${v}%`} />
        <Tile label="Departures/day" pre={data.departures_per_day.pre} post={data.departures_per_day.post} fmt={(v) => v.toLocaleString(undefined, { maximumFractionDigits: 0 })} />
      </div>

      {/* Route table */}
      {data.routes.length > 0 && (
        <div className="overflow-hidden rounded-xl border border-border">
          <table className="w-full text-xs">
            <thead className="bg-card-hover text-left text-[10px] uppercase tracking-wider text-text-muted">
              <tr>
                <th className="px-3 py-2">Route</th>
                <th className="px-3 py-2 text-right">n (pre/post)</th>
                <th className="px-3 py-2 text-right">On-time pre→post</th>
                <th className="px-3 py-2 text-right">Δ (pp)</th>
                <th className="px-3 py-2 text-right">Mean late pre→post</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border bg-card">
              {data.routes.map((r) => (
                <tr key={r.route}>
                  <td className="px-3 py-2 font-semibold text-text-primary">{r.route}</td>
                  <td className="px-3 py-2 text-right text-text-secondary">{r.n_pre.toLocaleString()}/{r.n_post.toLocaleString()}</td>
                  <td className="px-3 py-2 text-right text-text-secondary">{r.pct_on_time_pre}% → {r.pct_on_time_post}%</td>
                  <td className={`px-3 py-2 text-right font-semibold ${r.delta_pp < 0 ? 'text-bottleneck' : r.delta_pp > 0 ? 'text-optimized' : 'text-text-secondary'}`}>
                    {r.delta_pp > 0 ? '+' : ''}{r.delta_pp}
                  </td>
                  <td className="px-3 py-2 text-right text-text-secondary">
                    {r.mean_late_pre > 0 ? '+' : ''}{r.mean_late_pre} → {r.mean_late_post > 0 ? '+' : ''}{r.mean_late_post}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      <SourceNote
        source={data.sources.join(' · ')}
        period={`${pre.days} pre-block days · ${post.days} post-block days · ${data.n_observations_excluded.toLocaleString()} obs excluded (weekend/holiday/unclassifiable)`}
      />
    </div>
  );
}
